import RNA, random, sys
target = "((....))..(...(...(..(.(..(...(((.(((...((((....)))).((((((.((((((.((((((.((((((.((((((((((.((((((.(((((.((((.((((..((((...)))).))).)))))).))))).)))))).)))))))).)))))).)))))).)))))).))))))).)))...(((.(((((.(..((((.(..((((.(..((((.(..(((((((.((((((.(((((.((((((.(((.((((((....))))))..)))).)))).))))).)))))).)))))))).)..)))).)..)))).)..)))).)..))))).((((....))))...))).)))...)..).)..)...)...)..((....))"
N=len(target)

stack=[]; pairs={}
for i,c in enumerate(target):
    if c=='(':
        stack.append(i)
    elif c==')':
        j=stack.pop(); pairs[j]=i; pairs[i]=j

def find_loops(db):
    loops=[]
    for i in range(len(db)):
        if i in pairs and db[i]=='(':
            j=pairs[i]
            inner=db[i+1:j]
            if '(' not in inner and ')' not in inner:
                loops.append((i+1,j-1,i,j))
    return loops

LOOPS=find_loops(target)

def init_seq():
    seq=['A']*N
    for i,j in pairs.items():
        if i<j:
            seq[i]='C'; seq[j]='G'
    for s,e,i,j in LOOPS:
        L=e-s+1
        if L==4:
            seq[s:e+1]=list("GAAA"); seq[i]='G'; seq[j]='C'
        elif L==3:
            seq[s:e+1]=list("GAA"); seq[i]='C'; seq[j]='G'
    return ''.join(seq)

# find pair positions and unpaired positions that are "free" (not hairpin loop, not closing pair)
paired_pos=set()
closing_or_loop=set()
for i,j in pairs.items():
    paired_pos.add(i)
for s,e,i,j in LOOPS:
    for k in range(s,e+1): closing_or_loop.add(k)
    closing_or_loop.add(i); closing_or_loop.add(j)

free_positions=[i for i in range(N) if i not in paired_pos and i not in closing_or_loop]
# These are linkers / multiloop / bulges / internal loop unpaired. We can tune them.

# paired mutable positions (pairs we can flip to other valid pairs)
pair_list=sorted([i for i in pairs if i<pairs[i]])

def score(seq):
    fc=RNA.fold_compound(seq)
    ss,mfe=fc.mfe()
    return RNA.bp_distance(ss,target), ss

best=init_seq()
bd,ss=score(best)
print("start",bd)
best_score=bd

import time
t0=time.time()
random.seed(42)
iters=0
while time.time()-t0 < 150 and best_score>0:
    iters+=1
    cand=list(best)
    # mutation: pick a random free position and change, or flip a pair
    r=random.random()
    if r<0.6 and free_positions:
        p=random.choice(free_positions)
        cand[p]=random.choice("ACGU")
    elif r<0.8 and pair_list:
        i=random.choice(pair_list); j=pairs[i]
        # valid pairs: GC, CG, AU, UA, GU, UG
        pr=random.choice(["GC","CG","AU","UA","GU","UG"])
        cand[i]=pr[0]; cand[j]=pr[1]
    else:
        # multi mutation
        for _ in range(3):
            if free_positions:
                p=random.choice(free_positions)
                cand[p]=random.choice("ACGU")
    cand=''.join(cand)
    bd2,_=score(cand)
    if bd2<=best_score:
        if bd2<best_score or random.random()<0.3:
            best=cand; best_score=bd2
            if bd2==0:
                break

print("iters",iters,"best",best_score)
print(best)
with open('/tmp/cand.txt','w') as f:
    f.write(best)
