import RNA
# unit2 = "((((((.((((((.((((((.((((((.((((((((((.((((((.(((((.((((.((((..((((...)))).))).)))))).))))).)))))).)))))))).)))))).)))))).)))))).)))))))"
# This is a nested multi-hairpin. Innermost hairpin: ((((...)))) then expands.
# Let's solve the WHOLE nested structure as one but with the cap seeded.
# Try parallel_search with seeded init by using ViennaRNA constraint_fold? No.
# Instead: design by hand with GC stems + caps, fold, repair.
import RNA
target2 = "((((((.((((((.((((((.((((((.((((((((((.((((((.(((((.((((.((((..((((...)))).))).)))))).))))).)))))).)))))))).)))))).)))))).)))))).)))))))"
