for name,tgt in [("u2",target2),("u3",target3)]:
    N=len(tgt)
    stack=[]; pairs={}
    for i,c in enumerate(tgt):
        if c=='(':
            stack.append(i)
        elif c==')':
            j=stack.pop(); pairs[j]=i; pairs[i]=j
    def find_loops(db):
        loops=[]
        for i in range(len(db)):
            if i in pairs and db[i]=='(':
                j=pairs[i]
                inner=db[i+1:j]
                if '(' not in inner and ')' not in inner:
                    loops.append((i+1,j-1,i,j))
        return loops
    LOOPS=find_loops(tgt)
    seq=['A']*N
    for i,j in pairs.items():
        if i<j:
            seq[i]='G'; seq[j]='C'
    for s_,e_,i_,j_ in LOOPS:
        L=e_-s_+1
        if L==4:
            seq[s_:e_+1]=list("GAAA"); seq[i_]='G'; seq[j_]='C'
        elif L==3:
            seq[s_:e_+1]=list("GAA"); seq[i_]='C'; seq[j_]='G'
        else:
            seq[s_:e_+1]=list("A"*L)
    s=''.join(seq)
    fc=RNA.fold_compound(s)
    ss,mfe=fc.mfe()
    print(name,"len",N,"dist",RNA.bp_distance(ss,tgt))
    with open(f'/tmp/{name}_seed.txt','w') as f: f.write(s)
